const LOWER_LIMB_IMAGE_ROOT = "assets/lower-limb-clean";

function lowerLimbQuestion(text, options, explanation, image = "") {
  return { text, options, answer: 0, explanation, image };
}

function buildLowerLimbFactQuestions(facts) {
  const offsets = [1, 5, 9];

  return facts.flatMap((fact, index) => {
    const distractors = offsets.map((offset) => facts[(index + offset) % facts.length]);

    return [
      lowerLimbQuestion(
        `Hvilken struktur passer bedst til denne beskrivelse: ${fact.clue}`,
        [fact.name, ...distractors.map((item) => item.name)],
        fact.explanation
      ),
      lowerLimbQuestion(
        `Hvilket udsagn om ${fact.name} er korrekt?`,
        [fact.statement, ...distractors.map((item) => item.statement)],
        fact.explanation
      )
    ];
  });
}

function lowerLimbMaterial(id, title, description, facts, i18n) {
  return { id, title, description, i18n, questions: buildLowerLimbFactQuestions(facts) };
}

